let p=choice('answer','三個部分的段落範圍',2,['第1至3段／第4至7段／第8至10段','第1至3段／第4至8段／第9至10段','第1至4段／第5至7段／第8至10段','第1至4段／第5至8段／第9至10段'],'C');
add(9,'本篇共有10段，按結構可劃分為三個部分。以下哪一項的劃分最為合適？',[p],[official(p,['選C得2分；其餘0分。'])],
 lesson('segmentation',['segmentation','summary','technique','meaning'],'要求依內容組織劃分段落，不是概括單段或辨認修辭。',[1,4,5,7,8],['先各用一句話寫出第4、5、7、8段在談甚麼，哪些段落仍延續同一論點？','第5段提出哪種新說法？第8段把討論提升到哪個概念？比較四項邊界是否把相關內容拆開。'],['第1–4段談小說使人醒悟，王小波引文仍在說明現實生活的陷阱。','第5–7段反駁小說虛假之說，藉科羅和卡夫卡說明小說提供看待現實的新目光。','第8–10段集中說明文學目光的內容與影響；選C。'],['先找論點或討論角度的轉換，再劃分段落。','引用事例通常服務前文論點，不能一見人名或引文便另分一部分。']),
 {table:{headers:['選項','第一部分','第二部分','第三部分'],rows:[['A','第1至3段','第4至7段','第8至10段'],['B','第1至3段','第4至8段','第9至10段'],['C','第1至4段','第5至7段','第8至10段'],['D','第1至4段','第5至8段','第9至10段']]},optionAnalysis:options('answer',['第4段承接第3段的具體生活陷阱，不能與第一部分分開。','既把第4段與第一部分拆開，也把提出「文學目光」的第8段與後面的說明拆開。','三個部分依次討論醒悟、小說與真實、文學目光；兩個分界都有明確的論題轉換。','第8段已把重點集中到文學的目光，應與第9、10段的說明同屬第三部分。'])});

p=choice('answer','小說的價值',2,['揭示人生是冷漠和虛無的','令人敞開心扉體會人生是幸福的','令人逃離現實並找到安慰和期盼','讓人們重新思考人生並尋找意義'],'D');
add(10,'在第2段，作者藉《局外人》主角默爾索的故事說明小說有什麼價值？',[p],[official(p,['選D得2分；其餘0分。'])],
 lesson('meaning',['meaning','cause','trait','technique'],'要求由小說人物的經歷推到小說的價值，不能只複述故事結果。',[2,3],['分開默爾索醒悟之前和之後的看法；哪些內容是他原有的認知？','題目問小說的價值。哪個選項能說明這種改變如何幫助讀者，而不只重述人物感受？'],['冷漠虛無是醒悟前的狀態；醒悟使人物重新理解生活。','B複述人物感到幸福的結果，D才概括小說讓讀者反思人生、尋找意義的價值。','C把小說的作用說成逃避現實，與第3段鼓勵盤問自身的方向相反。'],['由事例推到論點時，分開人物經歷與作者藉此說明的普遍價值。','選項貼近原文字面未必完成題問的概括層次。']),
 {optionAnalysis:options('answer',['這是默爾索醒悟前的看法；故事的轉折正是突破冷漠與虛無。','這項只複述默爾索醒悟後的幸福感，未概括小說促使人重新思考人生的價值。','文中強調面對和反省生活，沒有說藉小說逃離現實。','由默爾索前後的轉變概括小說的價值：讓人重新理解自己的生活並尋找人生意義。'])});

p=short('answer','人們逃避＿＿的時刻（兩字詞）',2,{exactChars:2});
add(11,'在第3段，作者說在現實裏，人們總是逃避「這神奇的一刻」。人們逃避的是什麼時刻？答案須是兩字詞。',[p],
 [official(p,['答案必須是兩字詞；錯別字不扣分。','準確指出人們逃避的時刻得2分；概念或表述欠準確得1分。'],['覺醒／醒覺／醒悟／省悟／覺悟／悔悟／自省'],[example('覺察／覺知／懷疑／改變／清醒',1,'方向相關，但未準確概括質疑並重新理解自身生活的時刻。'),example('困苦／過往／自身／現實／真實',0,'只指處境、時間或對象，未指出所問的醒悟時刻。')],'2分：概括主人公質疑自己、推翻過往生活並醒悟的時刻。')],
 lesson('meaning',['meaning','summary','cause','trait'],'要求解開「這」的指代，再以兩字詞概括所指的時刻。',[3,2],['由「這神奇的一刻」往前讀，誰做了哪些思想上的動作？','把「懷疑」「推翻」及對生活的重新理解放在一起，找一個能涵蓋整個轉變的兩字詞。'],['「這」承接主人公質疑自身經歷、推翻過往生活的醒悟時刻。','覺醒、醒悟、自省等可準確概括；只寫「懷疑」或「改變」只到1分。','答案必須是兩字詞；不能以「現實」等被思考的對象代替思想轉變。'],['解指代先找前文完整事件，再用概括詞收束。','格式限制與概念準確都要符合；不要只摘最近的兩個字。']),
 {rubric:[{label:'指代',detail:'我概括的是思想轉變，不是逃避的處境或對象。'},{label:'格式',detail:'我的答案是兩字詞。'}]});

const effectChoices=['讓人們看到事物的關聯和意義','讓人們理解到時間的不同向度','讓人們對現實的理解更為具體','讓人們能面對孤獨無助的處境'];
let parts=[choice('i','(i)卡夫卡的故事（第6、7段）',2,effectChoices,'C'),choice('ii','(ii)《百年孤獨》的開頭（第10段）',2,effectChoices,'B')];
