parts=[choice('i','(i)這段文字運用了什麼修辭手法？',2,['(1)、(2)','(1)、(3)','(2)、(4)','(3)、(4)'],'A'),choice('ii','(ii)以下哪項有關這段文字的陳述最恰當？',2,['融情入景，韻味無窮','風趣滑稽，意在言外','描寫細緻，寓意深刻','構思巧妙，生動傳神'],'D')];
